// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // Fuzzed parameter: a bytes blob that will be forwarded as calldata to the callee.
    // We deploy a helper Reverter that always reverts on any call; this exposes the difference
    // because the reference propagates that failure (forward reverts) while the mutant inverts
    // the check and will NOT revert on a failing callee (or will behave oppositely).
    function testFuzz_property(bytes memory data) public {
        // keep domain wide; no need to bound data

        // Deploy a helper that ALWAYS reverts when called.
        Reverter rev = new Reverter();

        // Call c.forward with the reverter's address and fuzzed calldata. Observe whether c.forward
        // reverts by catching via try/catch and turning it into a boolean `ok`.
        bool ok;
        try c.forward(address(rev), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: For any calldata, forwarding to an ALWAYS-REVERT callee must itself revert
        // (so ok == false) on the correct contract. The mutant flips the revert logic and will
        // sometimes make ok == true for this same scenario. We assert the universal property here.
        assertTrue(!ok);
    }
}

// Adversarial counterparty: always revert on any call (including fallback/receive)
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
